// Generated by @canonical/summon-component:react v0.43.0

import { readFileSync } from "node:fs";
import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import TokenMark from "./TokenMark.js";

describe("TokenMark SSR", () => {
  it("renders both values inline on the server", () => {
    const html = renderToString(<TokenMark dark="#262626" light="#ffffff" />);
    expect(html).toContain('class="ds token-mark"');
    expect(html).toContain(
      '<span class="in-light" style="--token-mark-value:#ffffff">',
    );
    expect(html).toContain(
      '<span class="in-dark" style="--token-mark-value:#262626">',
    );
  });

  it("names no colour of its own: the wells read the channel, the frame the border colour", () => {
    const styles = readFileSync(
      new URL("./styles.css", import.meta.url),
      "utf8",
    );
    expect(
      styles.match(/background: var\(--token-mark-value\);/g),
    ).toHaveLength(2);
    expect(styles).toMatch(/--token-mark-border-color: var\(--color-border\);/);
    expect(styles).not.toMatch(/#[0-9a-f]{3,8}\b|rgb\(|hsl\(/i);
  });

  it("writes the oklch values the tokens hold and no style for a refused one", () => {
    const html = renderToString(
      <TokenMark
        dark="red;position:fixed;inset:0;background:url(//host/x.png)"
        light="oklch(100% 0.0131 23.19)"
      />,
    );
    expect(html).toContain(
      '<span class="in-light" style="--token-mark-value:oklch(100% 0.0131 23.19)">',
    );
    expect(html).toContain('<span class="in-dark"></span>');
    expect(html).not.toContain("position");
  });
});
